import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { clearStoryAuthCookies } from "@/platform/identity/cookies";
import { requireSupabaseSecretConfig } from "@/platform/persistence/config";
import { supabaseRest, supabaseStorageDelete } from "@/platform/persistence/supabase-rest";
export const runtime = "nodejs";
function sameOrigin(request: Request) { const origin = request.headers.get("origin"); if (!origin) return true; return new URL(origin).host === new URL(request.url).host; }
export async function DELETE(request: Request) {
  try {
    if (!sameOrigin(request)) return NextResponse.json({ error: "Invalid request origin." }, { status: 403 });
    const session = await requireStorySession(); const body = await request.json().catch(() => ({})) as { confirmation?: unknown };
    if (body.confirmation !== "DELETE") return NextResponse.json({ error: 'Type "DELETE" to confirm account deletion.' }, { status: 400 });
    const media = await supabaseRest<Array<{ object_path: string }>>("media_assets?select=object_path&limit=5000", session.token);
    for (const asset of media) await supabaseStorageDelete(asset.object_path, session.token).catch(() => undefined);
    const { url, secretKey } = requireSupabaseSecretConfig();
    const response = await fetch(`${url}/auth/v1/admin/users/${encodeURIComponent(session.user.id)}`, { method: "DELETE", headers: { apikey: secretKey, Authorization: `Bearer ${secretKey}` } });
    if (!response.ok) throw new Error("Supabase could not delete the account.");
    return clearStoryAuthCookies(NextResponse.json({ deleted: true }));
  } catch (cause) { const message = cause instanceof Error ? cause.message : "Could not delete account."; return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : 400 }); }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";
export const runtime = "nodejs";
export async function GET() {
  try {
    const session = await requireStorySession();
    const [profiles, worlds, events, albums, albumItems, tracks] = await Promise.all([
      supabaseRest<Array<Record<string, unknown>>>("profiles?select=user_id,display_name,timezone,locale,interests,created_at,updated_at", session.token),
      supabaseRest<Array<Record<string, unknown>>>("worlds?select=id,product,title,anchor_date,visibility,summary,created_at,updated_at&order=created_at.asc", session.token),
      supabaseRest<Array<Record<string, unknown>>>("story_events?select=id,world_id,product,event_type,occurred_at,title,description,people,location,metadata,created_at&order=occurred_at.asc&limit=5000", session.token),
      supabaseRest<Array<Record<string, unknown>>>("albums?select=id,world_id,title,description,start_date,end_date,privacy,created_at,updated_at&order=created_at.asc", session.token),
      supabaseRest<Array<Record<string, unknown>>>("album_items?select=album_id,media_id,position,caption,occurred_at,is_favorite&order=position.asc&limit=5000", session.token),
      supabaseRest<Array<Record<string, unknown>>>("music_tracks?select=id,title,artist,album,external_url,provider,memory_date,note,created_at&order=created_at.asc", session.token),
    ]);
    return NextResponse.json({ version: 1, exportedAt: new Date().toISOString(), profile: profiles[0] ?? null, worlds, events, albums, albumItems, musicTracks: tracks }, { headers: { "Content-Disposition": 'attachment; filename="threadtales-account-export.json"', "Cache-Control": "no-store" } });
  } catch (cause) { const message = cause instanceof Error ? cause.message : "Could not export account data."; return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : 400 }); }
}

import { NextResponse } from "next/server";
import { getStoryEnrichmentProvider } from "@/platform/ai/openai-provider";
import { validateStoryEnrichmentInput, type StoryEnrichmentInput } from "@/platform/ai/types";

export const runtime = "nodejs";

export async function GET() {
  return NextResponse.json({ enabled: Boolean(getStoryEnrichmentProvider()), provider: getStoryEnrichmentProvider()?.name ?? null });
}

export async function POST(request: Request) {
  try {
    const provider = getStoryEnrichmentProvider();
    if (!provider) return NextResponse.json({ error: "Optional AI enrichment is not configured." }, { status: 503 });
    const input = await request.json() as StoryEnrichmentInput;
    validateStoryEnrichmentInput(input);
    const result = await provider.enrich(input);
    return NextResponse.json(result);
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "AI enrichment failed.";
    return NextResponse.json({ error: message }, { status: /consent|rejected|invalid|unsupported|too/i.test(message) ? 400 : 502 });
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";
import { getUserSubscription } from "@/platform/billing/subscription";
import { planCatalog } from "@/platform/billing/plans";

export const runtime = "nodejs";

export async function POST(request: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession();
    const { id } = await context.params;
    if (!/^[0-9a-f-]{36}$/i.test(id)) return NextResponse.json({ error: "Invalid album id." }, { status: 400 });
    const albums = await supabaseRest<{ id: string; owner_id: string }[]>(`albums?id=eq.${id}&select=id,owner_id`, session.token);
    if (!albums[0]) return NextResponse.json({ error: "Album not found." }, { status: 404 });
    const body = await request.json() as { mediaId?: unknown; caption?: unknown; occurredAt?: unknown };
    if (typeof body.mediaId !== "string" || !/^[0-9a-f-]{36}$/i.test(body.mediaId)) return NextResponse.json({ error: "Choose valid media." }, { status: 400 });
    const media = await supabaseRest<{ id: string }[]>(`media_assets?id=eq.${body.mediaId}&select=id`, session.token);
    if (!media[0]) return NextResponse.json({ error: "Media not found." }, { status: 404 });
    const existing = await supabaseRest<{ media_id: string }[]>(`album_items?album_id=eq.${id}&select=media_id&limit=5000`, session.token);
    const subscription = await getUserSubscription(session.user.id, session.token).catch(() => ({ plan_slug: "free" as const, status: "free" }));
    const max = planCatalog[subscription.plan_slug].maxAlbumItems;
    if (existing.length >= max) return NextResponse.json({ error: `Your ${planCatalog[subscription.plan_slug].label} plan supports ${max} items per album.` }, { status: 409 });
    const payload = { album_id: id, media_id: body.mediaId, position: existing.length, caption: typeof body.caption === "string" ? body.caption.trim().slice(0, 500) || null : null, occurred_at: typeof body.occurredAt === "string" ? body.occurredAt || null : null };
    const rows = await supabaseRest<Record<string, unknown>[]>("album_items", session.token, { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(payload) });
    return NextResponse.json({ item: rows[0] }, { status: 201 });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not add media to album.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function PATCH(request: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession();
    const { id } = await context.params;
    const body = await request.json() as { items?: Array<{ mediaId: string; position: number; caption?: string; favorite?: boolean }> };
    if (!/^[0-9a-f-]{36}$/i.test(id) || !Array.isArray(body.items) || body.items.length > 2000) return NextResponse.json({ error: "Invalid album update." }, { status: 400 });
    for (const item of body.items) {
      if (!/^[0-9a-f-]{36}$/i.test(item.mediaId) || !Number.isInteger(item.position) || item.position < 0) continue;
      const update = { position: item.position, ...(typeof item.caption === "string" ? { caption: item.caption.trim().slice(0, 500) || null } : {}), ...(typeof item.favorite === "boolean" ? { is_favorite: item.favorite } : {}) };
      await supabaseRest<null>(`album_items?album_id=eq.${id}&media_id=eq.${item.mediaId}`, session.token, { method: "PATCH", headers: { Prefer: "return=minimal" }, body: JSON.stringify(update) });
    }
    return NextResponse.json({ updated: true });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not reorder album.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function DELETE(request: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession();
    const { id } = await context.params;
    const mediaId = new URL(request.url).searchParams.get("mediaId") ?? "";
    if (!/^[0-9a-f-]{36}$/i.test(id) || !/^[0-9a-f-]{36}$/i.test(mediaId)) return NextResponse.json({ error: "Invalid album item." }, { status: 400 });
    await supabaseRest<null>(`album_items?album_id=eq.${id}&media_id=eq.${mediaId}`, session.token, { method: "DELETE", headers: { Prefer: "return=minimal" } });
    return NextResponse.json({ deleted: true });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not remove album item.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest, supabaseStorageSignedUrl } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

function validId(id: string) { return /^[0-9a-f-]{36}$/i.test(id); }

export async function GET(_: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession();
    const { id } = await context.params;
    if (!validId(id)) return NextResponse.json({ error: "Invalid album id." }, { status: 400 });
    const albums = await supabaseRest<Record<string, unknown>[]>(`albums?id=eq.${id}&select=*`, session.token);
    if (!albums[0]) return NextResponse.json({ error: "Album not found." }, { status: 404 });
    const items = await supabaseRest<{ album_id: string; media_id: string; position: number; caption?: string | null; occurred_at?: string | null; is_favorite?: boolean }[]>(`album_items?album_id=eq.${id}&select=*&order=position.asc`, session.token);
    const mediaIds = items.map((item) => item.media_id);
    const media = mediaIds.length ? await supabaseRest<{ id: string; object_path: string; mime_type?: string | null; media_kind: string; caption?: string | null; occurred_at?: string | null }[]>(`media_assets?id=in.(${mediaIds.join(",")})&select=id,object_path,mime_type,media_kind,caption,occurred_at`, session.token) : [];
    const hydrated = await Promise.all(media.map(async (asset) => ({ ...asset, signedUrl: await supabaseStorageSignedUrl(asset.object_path, session.token).catch(() => null) })));
    const soundtrack = await supabaseRest<{ track_id: string; position: number }[]>(`album_music_tracks?album_id=eq.${id}&select=track_id,position&order=position.asc`, session.token);
    return NextResponse.json({ album: albums[0], items, media: hydrated, soundtrack });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not load album.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function PATCH(request: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession();
    const { id } = await context.params;
    if (!validId(id)) return NextResponse.json({ error: "Invalid album id." }, { status: 400 });
    const body = await request.json() as { title?: unknown; description?: unknown; coverMediaId?: unknown; startDate?: unknown; endDate?: unknown };
    const update: Record<string, unknown> = { updated_at: new Date().toISOString() };
    if (typeof body.title === "string" && body.title.trim()) update.title = body.title.trim().slice(0, 120);
    if (typeof body.description === "string") update.description = body.description.trim().slice(0, 1000) || null;
    if (body.coverMediaId === null || (typeof body.coverMediaId === "string" && validId(body.coverMediaId))) update.cover_media_id = body.coverMediaId;
    if (typeof body.startDate === "string" && /^\d{4}-\d{2}-\d{2}$/.test(body.startDate)) update.start_date = body.startDate;
    if (typeof body.endDate === "string" && /^\d{4}-\d{2}-\d{2}$/.test(body.endDate)) update.end_date = body.endDate;
    const rows = await supabaseRest<Record<string, unknown>[]>(`albums?id=eq.${id}`, session.token, { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify(update) });
    if (!rows[0]) return NextResponse.json({ error: "Album not found." }, { status: 404 });
    return NextResponse.json({ album: rows[0] });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not update album.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function DELETE(_: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession();
    const { id } = await context.params;
    if (!validId(id)) return NextResponse.json({ error: "Invalid album id." }, { status: 400 });
    await supabaseRest<null>(`albums?id=eq.${id}`, session.token, { method: "DELETE", headers: { Prefer: "return=minimal" } });
    return NextResponse.json({ deleted: true });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not delete album.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";
export const runtime = "nodejs";
function valid(value: unknown) { return typeof value === "string" && /^[0-9a-f-]{36}$/i.test(value); }
export async function POST(request: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession(); const { id: albumId } = await context.params; const body = await request.json() as { trackId?: unknown };
    if (!valid(albumId) || !valid(body.trackId)) return NextResponse.json({ error: "Invalid soundtrack selection." }, { status: 400 });
    const [albums, tracks, current] = await Promise.all([
      supabaseRest<Array<{ id: string }>>(`albums?id=eq.${albumId}&select=id`, session.token),
      supabaseRest<Array<{ id: string }>>(`music_tracks?id=eq.${body.trackId}&select=id`, session.token),
      supabaseRest<Array<{ track_id: string }>>(`album_music_tracks?album_id=eq.${albumId}&select=track_id`, session.token),
    ]);
    if (!albums[0] || !tracks[0]) return NextResponse.json({ error: "Album or song not found." }, { status: 404 });
    const rows = await supabaseRest<Array<Record<string, unknown>>>("album_music_tracks", session.token, { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify({ album_id: albumId, track_id: body.trackId, position: current.length }) });
    return NextResponse.json({ soundtrackItem: rows[0] }, { status: 201 });
  } catch (cause) { const message = cause instanceof Error ? cause.message : "Could not update album soundtrack."; return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : 400 }); }
}
export async function DELETE(request: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const session = await requireStorySession(); const { id: albumId } = await context.params; const trackId = new URL(request.url).searchParams.get("trackId");
    if (!valid(albumId) || !valid(trackId)) return NextResponse.json({ error: "Invalid soundtrack selection." }, { status: 400 });
    await supabaseRest(`album_music_tracks?album_id=eq.${albumId}&track_id=eq.${trackId}`, session.token, { method: "DELETE", headers: { Prefer: "return=minimal" } });
    return NextResponse.json({ deleted: true });
  } catch (cause) { const message = cause instanceof Error ? cause.message : "Could not update album soundtrack."; return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : 400 }); }
}

import { NextResponse } from "next/server";
import { requireStorySession } from "@/platform/identity/session";
import { supabaseRest } from "@/platform/persistence/supabase-rest";

export const runtime = "nodejs";

type AlbumRow = { id: string; world_id: string; owner_id: string; title: string; description?: string | null; cover_media_id?: string | null; start_date?: string | null; end_date?: string | null; privacy: string; created_at: string; updated_at: string };

export async function GET(request: Request) {
  try {
    const session = await requireStorySession();
    const world = new URL(request.url).searchParams.get("world");
    const filter = world && /^[0-9a-f-]{36}$/i.test(world) ? `&world_id=eq.${world}` : "";
    const albums = await supabaseRest<AlbumRow[]>(`albums?select=*&order=updated_at.desc${filter}&limit=100`, session.token);
    return NextResponse.json({ albums });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not load albums.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

export async function POST(request: Request) {
  try {
    const session = await requireStorySession();
    const body = await request.json() as { worldId?: unknown; title?: unknown; description?: unknown; startDate?: unknown; endDate?: unknown };
    if (typeof body.worldId !== "string" || !/^[0-9a-f-]{36}$/i.test(body.worldId)) return NextResponse.json({ error: "Choose a world for this album." }, { status: 400 });
    const worlds = await supabaseRest<{ id: string }[]>(`worlds?id=eq.${body.worldId}&select=id`, session.token);
    if (!worlds[0]) return NextResponse.json({ error: "World not found." }, { status: 404 });
    const title = typeof body.title === "string" ? body.title.trim().slice(0, 120) : "";
    if (!title) return NextResponse.json({ error: "Album title is required." }, { status: 400 });
    const payload = { world_id: body.worldId, owner_id: session.user.id, title, description: typeof body.description === "string" ? body.description.trim().slice(0, 1000) || null : null, start_date: typeof body.startDate === "string" && /^\d{4}-\d{2}-\d{2}$/.test(body.startDate) ? body.startDate : null, end_date: typeof body.endDate === "string" && /^\d{4}-\d{2}-\d{2}$/.test(body.endDate) ? body.endDate : null, privacy: "private" };
    const rows = await supabaseRest<AlbumRow[]>("albums", session.token, { method: "POST", headers: { Prefer: "return=representation" }, body: JSON.stringify(payload) });
    return NextResponse.json({ album: rows[0] }, { status: 201 });
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not create album.";
    return NextResponse.json({ error: message === "AUTH_REQUIRED" ? "Authentication required." : message }, { status: message === "AUTH_REQUIRED" ? 401 : /not configured/i.test(message) ? 503 : 400 });
  }
}

import { NextResponse } from "next/server";
import { signInWithPassword } from "@/platform/persistence/supabase-rest";
import { setStoryAuthCookies } from "@/platform/identity/cookies";

export const runtime = "nodejs";

export async function POST(request: Request) {
  try {
    const body = await request.json() as { email?: string; password?: string };
    const session = await signInWithPassword(body.email ?? "", body.password ?? "");
    return setStoryAuthCookies(NextResponse.json({ authenticated: true }), session);
  } catch (cause) {
    const message = cause instanceof Error ? cause.message : "Could not sign in.";
    return NextResponse.json({ error: /not configured/i.test(message) ? message : "Email or password is incorrect, or the account has not been verified yet." }, { status: /not configured/i.test(message) ? 503 : 401 });
  }
}

